#pragma once
#include "gradient_map.h"
#include <filesystem>
#include <fstream>
#include <sstream>
#include <roapi.h>
#include <windows.h>
#ifdef GetObject
#undef GetObject
#endif
#include <winrt/Windows.Foundation.Collections.h>
#include <winrt/Windows.Data.Json.h>
#pragma comment(lib,"windowsapp.lib")
namespace moon {
struct SavedGradientMapPreset {std::string name;GradientMapSettings settings;};
class GradientMapPresetStore {
 std::filesystem::path path_,hiddenPath_;using Json=winrt::Windows::Data::Json::JsonObject;using Array=winrt::Windows::Data::Json::JsonArray;using Value=winrt::Windows::Data::Json::JsonValue;
 struct Apartment{HRESULT status=RoInitialize(RO_INIT_MULTITHREADED);Apartment(){if(FAILED(status)&&status!=RPC_E_CHANGED_MODE)throw std::runtime_error("Cannot initialize JSON parser");}~Apartment(){if(SUCCEEDED(status)){winrt::clear_factory_cache();RoUninitialize();}}};
 static std::string text(const std::filesystem::path& path){std::ifstream in(path,std::ios::binary);if(!in){if(!std::filesystem::exists(path))return {};throw std::runtime_error("Cannot read gradient preset library");}std::ostringstream out;out<<in.rdbuf();if(in.bad())throw std::runtime_error("Cannot read gradient preset library");return out.str();}
 static void atomicWrite(const std::filesystem::path& path,const std::string& value){if(GetFileAttributesW(path.parent_path().c_str())==INVALID_FILE_ATTRIBUTES)std::filesystem::create_directories(path.parent_path());auto temporary=path;temporary+=L".pending-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64());try{std::ofstream out(temporary,std::ios::binary|std::ios::trunc);out.exceptions(std::ios::failbit|std::ios::badbit);out<<value;out.close();if(!MoveFileExW(temporary.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Cannot write gradient preset library");}catch(...){std::error_code error;std::filesystem::remove(temporary,error);throw;}}
 static const std::array<const char*,9>& dithers(){static const std::array<const char*,9> names{"none","bayer-2","bayer-4","bayer-8","checker","diagonal","diagonal-reverse","horizontal","vertical"};return names;}
 static const std::array<const char*,8>& keys(){static const std::array<const char*,8> names{"gradientMap.grayscale","gradientMap.silver","gradientMap.gold","gradientMap.copper","gradientMap.ocean","gradientMap.sunset","gradientMap.gameboy","gradientMap.sepia"};return names;}
 static std::string trimmed(std::string name){auto wide=winrt::to_hstring(name);std::wstring_view view(wide);auto whitespace=[](wchar_t c){return c==0x9||c==0xa||c==0xb||c==0xc||c==0xd||c==0x20||c==0xa0||c==0x1680||(c>=0x2000&&c<=0x200a)||c==0x2028||c==0x2029||c==0x202f||c==0x205f||c==0x3000||c==0xfeff;};while(!view.empty()&&whitespace(view.front()))view.remove_prefix(1);while(!view.empty()&&whitespace(view.back()))view.remove_suffix(1);return winrt::to_string(view.substr(0,80));}
 static Json encodeSettings(GradientMapSettings value){value=normalizeGradientMap(value);Json o;Array stops;for(auto stop:value.stops){Json s,c;s.SetNamedValue(L"position",Value::CreateNumberValue(stop.position));for(int i=0;i<4;++i)c.SetNamedValue(winrt::to_hstring(std::string(1,"rgba"[i])),Value::CreateNumberValue((stop.color>>(8*i))&255));s.SetNamedValue(L"color",c);stops.Append(s);}o.SetNamedValue(L"stops",stops);o.SetNamedValue(L"mode",Value::CreateStringValue(value.steps?L"steps":L"continuous"));o.SetNamedValue(L"dither",Value::CreateStringValue(winrt::to_hstring(dithers()[value.dither])));o.SetNamedValue(L"reverse",Value::CreateBooleanValue(value.reverse));return o;}
 static GradientMapSettings decodeSettings(Json o){GradientMapSettings s;s.stops.clear();auto stops=o.GetNamedArray(L"stops");for(std::uint32_t i=0;i<std::min<std::uint32_t>(256,stops.Size());++i){auto v=stops.GetAt(i);if(v.ValueType()!=winrt::Windows::Data::Json::JsonValueType::Object)continue;auto stop=v.GetObject();if(!stop.HasKey(L"position")||stop.GetNamedValue(L"position").ValueType()!=winrt::Windows::Data::Json::JsonValueType::Number||!stop.HasKey(L"color")||stop.GetNamedValue(L"color").ValueType()!=winrt::Windows::Data::Json::JsonValueType::Object)continue;double p=stop.GetNamedNumber(L"position");if(!std::isfinite(p))continue;auto color=stop.GetNamedObject(L"color");std::uint32_t packed=0xff000000;for(int c=0;c<3;++c){auto key=winrt::to_hstring(std::string(1,"rgb"[c]));double n=color.HasKey(key)&&color.GetNamedValue(key).ValueType()==winrt::Windows::Data::Json::JsonValueType::Number?color.GetNamedNumber(key):0;packed|=std::uint32_t(std::isfinite(n)?gradientRound(std::clamp(n,0.0,255.0)):0)<<(8*c);}s.stops.push_back({p,packed});}s.steps=o.HasKey(L"mode")&&o.GetNamedValue(L"mode").ValueType()==winrt::Windows::Data::Json::JsonValueType::String&&o.GetNamedString(L"mode")==L"steps";auto d=o.HasKey(L"dither")&&o.GetNamedValue(L"dither").ValueType()==winrt::Windows::Data::Json::JsonValueType::String?o.GetNamedString(L"dither"):winrt::hstring(L"none");for(int i=0;i<9;++i)if(d==winrt::to_hstring(dithers()[i]))s.dither=i;s.reverse=o.HasKey(L"reverse")&&o.GetNamedValue(L"reverse").ValueType()==winrt::Windows::Data::Json::JsonValueType::Boolean&&o.GetNamedBoolean(L"reverse");return normalizeGradientMap(s);}
public:
 explicit GradientMapPresetStore(std::filesystem::path directory):path_(directory/"gradient-map-presets.v1.json"),hiddenPath_(directory/"gradient-map-hidden-builtins.v1.json"){}
 const std::filesystem::path& path()const{return path_;}
 std::vector<SavedGradientMapPreset> load()const try{Apartment apartment;auto raw=text(path_);if(raw.empty()){if(std::filesystem::exists(path_))throw std::runtime_error("Invalid gradient preset data");return {};}auto data=Array::Parse(winrt::to_hstring(raw));if(data.Size()>100)throw std::runtime_error("Invalid gradient preset data");std::vector<SavedGradientMapPreset> result;for(auto value:data){auto o=value.GetObject();auto name=trimmed(winrt::to_string(o.GetNamedString(L"name")));auto settings=o.GetNamedObject(L"settings");auto stops=settings.GetNamedArray(L"stops");if(name.empty()||stops.Size()<2||stops.Size()>256)throw std::runtime_error("Invalid gradient preset");result.push_back({name,decodeSettings(settings)});}return result;}catch(const winrt::hresult_error& e){throw std::runtime_error(winrt::to_string(e.message()));}
 std::vector<SavedGradientMapPreset> save(std::string name,GradientMapSettings settings)const{auto presets=load();name=trimmed(name);if(name.empty())throw std::runtime_error("A gradient preset needs a name");presets.erase(std::remove_if(presets.begin(),presets.end(),[&](auto p){return p.name==name;}),presets.end());presets.push_back({name,normalizeGradientMap(settings)});if(presets.size()>100)throw std::runtime_error("Gradient preset library is full");store(presets);return presets;}
 std::vector<SavedGradientMapPreset> remove(const std::string& name)const{auto presets=load();presets.erase(std::remove_if(presets.begin(),presets.end(),[&](auto p){return p.name==name;}),presets.end());store(presets);return presets;}
 std::vector<int> hidden()const try{Apartment apartment;auto raw=text(hiddenPath_);if(raw.empty()){if(std::filesystem::exists(hiddenPath_))throw std::runtime_error("Invalid hidden gradient presets");return {};}auto array=Array::Parse(winrt::to_hstring(raw));std::vector<int> out;for(auto v:array){auto key=v.GetString();for(int i=0;i<8;++i)if(key==winrt::to_hstring(keys()[i]))out.push_back(i);}return out;}catch(const winrt::hresult_error& e){throw std::runtime_error(winrt::to_string(e.message()));}
 std::vector<int> hide(int index)const{if(index<0||index>=8)throw std::runtime_error("Unknown gradient preset");auto h=hidden();if(std::find(h.begin(),h.end(),index)==h.end())h.push_back(index);Apartment apartment;Array array;for(int i:h)array.Append(Value::CreateStringValue(winrt::to_hstring(keys()[i])));atomicWrite(hiddenPath_,winrt::to_string(array.Stringify()));return h;}
 static bool validName(const std::string& name){return !trimmed(name).empty();}
private:
 void store(const std::vector<SavedGradientMapPreset>& presets)const try{Apartment apartment;Array array;for(const auto& preset:presets){Json o;o.SetNamedValue(L"name",Value::CreateStringValue(winrt::to_hstring(preset.name)));o.SetNamedValue(L"settings",encodeSettings(preset.settings));array.Append(o);}atomicWrite(path_,winrt::to_string(array.Stringify()));}catch(const winrt::hresult_error& e){throw std::runtime_error(winrt::to_string(e.message()));}
};
}
